// ── Library Folder Tests ──
// `POST /Library/VirtualFolders` stores a library only if every path is a folder
// the server can list. Otherwise it answers 400, names each bad path in `Detail`
// and stores nothing.

/// A server with one library, "Films", whose lists have been read and so are cached.
struct ServerWithFilms {
    state: AppState,
    app: axum::Router,
    token: String,
    user_id: uuid::Uuid,
}

async fn server_with_films() -> ServerWithFilms {
    let state = test_state().await;
    let (token, user_id) = admin_session(&state).await;
    let app = app(state.clone());
    create_library_via_api(&app, &state, &token, "Films", "Movies").await;
    assert_listed_libraries(&app, &token, user_id, &["Films"]).await;
    assert!(state.cache.library_views.get("views").is_some());
    ServerWithFilms {
        state,
        app,
        token,
        user_id,
    }
}

/// Writes the file `media/<name>` in the test's data dir and returns its path.
fn media_file(state: &AppState, name: &str) -> String {
    let file = state.data_dir.join("media").join(name);
    std::fs::create_dir_all(file.parent().unwrap()).unwrap();
    std::fs::write(&file, b"not a folder").unwrap();
    file.to_str().unwrap().to_string()
}

/// Sends `POST /Library/VirtualFolders` for a TV library called "Shows" on `paths`.
async fn create_shows(server: &ServerWithFilms, paths: &[&str]) -> (StatusCode, serde_json::Value) {
    let body = serde_json::json!({ "Name": "Shows", "ContentType": "TvShows", "Paths": paths });
    send_authed(
        &server.app,
        "POST",
        "/Library/VirtualFolders",
        &server.token,
        Some(&body.to_string()),
    )
    .await
}

/// Asserts that creating "Shows" on `paths` fails with 400 and exactly `detail`,
/// and that it left the cached views, every list and the stored libraries alone.
async fn assert_shows_rejected(server: &ServerWithFilms, paths: &[&str], detail: &str) {
    let (status, body) = create_shows(server, paths).await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "create on {paths:?}: {body}"
    );
    assert_eq!(body["Title"], "Bad Request");
    assert_eq!(body["Status"], 400);
    assert_eq!(body["Detail"], detail, "Detail for {paths:?}");
    assert!(
        server.state.cache.library_views.get("views").is_some(),
        "a rejected create must leave the cached views alone"
    );
    assert_listed_libraries(&server.app, &server.token, server.user_id, &["Films"]).await;
    assert_eq!(stored_library_names(&server.state).await, ["Films"]);
}

#[tokio::test]
async fn test_create_library_rejects_missing_folder() {
    let server = server_with_films().await;
    let missing = server.state.data_dir.join("media").join("shows");
    let missing = missing.to_str().unwrap();
    // A path below a file is missing too, though the OS reports "not a directory".
    let below_file = format!("{}/shows", media_file(&server.state, "shows.mkv"));

    assert_shows_rejected(
        &server,
        &[missing, &below_file],
        &format!(
            "The folder \"{missing}\" was not found on the server. \
             The folder \"{below_file}\" was not found on the server."
        ),
    )
    .await;
}

#[tokio::test]
async fn test_create_library_rejects_relative_path() {
    let server = server_with_films().await;

    // "." exists and can be listed, so only the full-path check can refuse it.
    assert_shows_rejected(
        &server,
        &["."],
        "The folder \".\" is not a full path on the server.",
    )
    .await;
}

#[tokio::test]
async fn test_create_library_rejects_file_path() {
    let server = server_with_films().await;
    let file = media_file(&server.state, "shows.mkv");

    assert_shows_rejected(
        &server,
        &[&file],
        &format!("The path \"{file}\" on the server is not a folder."),
    )
    .await;
}

#[cfg(unix)]
#[tokio::test]
async fn test_create_library_rejects_unreadable_folder() {
    use std::os::unix::fs::PermissionsExt;

    /// Gives the folder its mode back when the test ends, even if it fails, so
    /// that the test's data dir can be deleted.
    struct Unlock<'a>(&'a str);
    impl Drop for Unlock<'_> {
        fn drop(&mut self) {
            let _ = std::fs::set_permissions(self.0, std::fs::Permissions::from_mode(0o755));
        }
    }

    let server = server_with_films().await;
    let locked = media_folder(&server.state, "shows");
    std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();
    let _unlock = Unlock(&locked);
    if std::fs::read_dir(&locked).is_ok() {
        eprintln!("skipped: this process can list a folder with mode 000 (running as root?)");
        return;
    }

    assert_shows_rejected(
        &server,
        &[&locked],
        &format!("The server does not have permission to read the folder \"{locked}\"."),
    )
    .await;
}

#[tokio::test]
async fn test_create_library_with_any_bad_path_stores_nothing() {
    let server = server_with_films().await;
    let good = media_folder(&server.state, "shows");
    let missing = server.state.data_dir.join("media").join("more shows");
    let missing = missing.to_str().unwrap();
    let file = media_file(&server.state, "episode.mkv");

    // Only the bad paths are named, in the order they were sent.
    assert_shows_rejected(
        &server,
        &[&good, missing, "shows", &file],
        &format!(
            "The folder \"{missing}\" was not found on the server. \
             The folder \"shows\" is not a full path on the server. \
             The path \"{file}\" on the server is not a folder."
        ),
    )
    .await;
}

#[tokio::test]
async fn test_create_library_accepts_existing_folders() {
    let server = server_with_films().await;
    let shows = media_folder(&server.state, "shows");
    // Paths are stored as sent, trailing slash included.
    let more_shows = format!("{}/", media_folder(&server.state, "more shows"));

    let (status, created) = create_shows(&server, &[&shows, &more_shows]).await;
    assert_eq!(status, StatusCode::OK, "create Shows: {created}");
    assert_eq!(created["Name"], "Shows");
    assert_eq!(created["Paths"], serde_json::json!([shows, more_shows]));

    assert_listed_libraries(
        &server.app,
        &server.token,
        server.user_id,
        &["Films", "Shows"],
    )
    .await;
    assert_eq!(
        stored_library_names(&server.state).await,
        ["Films", "Shows"]
    );
    let id = created["Id"].as_str().unwrap().parse().unwrap();
    let stored = rustyfin_db::repo_library::get_library_by_id(&server.state.db, id)
        .await
        .unwrap()
        .unwrap();
    assert_eq!(stored.paths, [shows, more_shows]);
}

// B118: wizard library

/// Sends `POST /Environment/ValidatePath` for `path`, with `token` if given.
async fn b118_validate(
    app: &axum::Router,
    token: Option<&str>,
    path: &str,
) -> (StatusCode, serde_json::Value) {
    let body = serde_json::json!({ "Path": path, "ValidateWritable": false });
    send(
        app,
        request("POST", "/Environment/ValidatePath", token, Some(body)),
    )
    .await
}

#[tokio::test]
async fn b118_validate_path_accepts_folder_before_owner() {
    let state = test_state().await;
    let app = app(state.clone());
    let folder = media_folder(&state, "b118 shows");
    // Paths are checked as sent, trailing slash included.
    for path in [folder.clone(), format!("{folder}/")] {
        let (status, body) = b118_validate(&app, None, &path).await;
        assert_eq!(status, StatusCode::NO_CONTENT, "validate {path}: {body}");
    }
    assert!(
        stored_library_names(&state).await.is_empty(),
        "a path check must store no library"
    );
}

#[tokio::test]
async fn b118_validate_path_rejects_with_create_sentences() {
    let state = test_state().await;
    let app = app(state.clone());
    let missing = state.data_dir.join("media").join("b118 missing");
    let missing = missing.to_str().unwrap().to_string();
    let file = media_file(&state, "b118 episode.mkv");
    let below_file = format!("{file}/shows");
    // Like Jellyfin, a path that is not an existing folder answers 404; other problems answer 400.
    let cases = [
        (
            missing.clone(),
            StatusCode::NOT_FOUND,
            format!("The folder \"{missing}\" was not found on the server."),
        ),
        (
            below_file.clone(),
            StatusCode::NOT_FOUND,
            format!("The folder \"{below_file}\" was not found on the server."),
        ),
        (
            ".".to_string(),
            StatusCode::BAD_REQUEST,
            "The folder \".\" is not a full path on the server.".to_string(),
        ),
        (
            String::new(),
            StatusCode::BAD_REQUEST,
            "The folder \"\" is not a full path on the server.".to_string(),
        ),
        (
            file.clone(),
            StatusCode::NOT_FOUND,
            format!("The path \"{file}\" on the server is not a folder."),
        ),
    ];
    for (path, expected, detail) in cases {
        let (status, body) = b118_validate(&app, None, &path).await;
        assert_eq!(status, expected, "validate {path:?}: {body}");
        assert_eq!(body["Status"], expected.as_u16());
        assert_eq!(body["Detail"], detail.as_str(), "Detail for {path:?}");
    }
    assert!(stored_library_names(&state).await.is_empty());
}

#[tokio::test]
async fn b118_validate_path_admin_only_after_owner() {
    let state = test_state().await;
    let app = app(state.clone());
    let (owner, _, viewer, _) = g1_owner_and_viewer(&state, &app).await;
    let body = serde_json::json!({ "Path": media_folder(&state, "b118 owner") });
    let routes = [(
        "POST",
        "/Environment/ValidatePath".to_string(),
        Some(body),
        true,
    )];
    g1_check_admin_routes(&app, &routes, &owner, &viewer).await;
    let missing = state.data_dir.join("media").join("b118 gone");
    let (status, body) = b118_validate(&app, Some(&owner), missing.to_str().unwrap()).await;
    assert_eq!(status, StatusCode::NOT_FOUND, "owner, missing path: {body}");
    let (status, body) =
        b118_validate(&app, Some(&owner), &media_folder(&state, "b118 owner")).await;
    assert_eq!(status, StatusCode::NO_CONTENT, "owner, folder: {body}");
}

// B124: wizard Enter. Enter in a wizard field does what the step's primary button does.
fn b124_web_source(file: &str) -> String {
    std::fs::read_to_string(format!(
        "{}/../rustyfin-web/src/{file}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .unwrap()
}

// A top-level function of app.js, from its head to its closing brace.
fn b124_function(app_js: &str, head: &str) -> String {
    let start = app_js
        .find(head)
        .unwrap_or_else(|| panic!("app.js has {head}"));
    let rest = &app_js[start..];
    rest[..rest.find("\n}\n").unwrap()].to_string()
}

// Runs a node test of tests/web/ against app.js. Without node it fails rather than skip:
// CI's Check job installs nodejs so that these tests run there.
fn b124_node_test(script: &str) {
    let dir = env!("CARGO_MANIFEST_DIR");
    let out = std::process::Command::new("node")
        .arg(format!("{dir}/tests/web/{script}"))
        .arg(format!("{dir}/../rustyfin-web/src/app.js"))
        .output()
        .unwrap_or_else(|e| panic!("{script} needs node on PATH: {e}"));
    assert!(
        out.status.success(),
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
}

#[test]
fn b124_wizard_enter_listener() {
    b124_node_test("b124_wizard_enter.mjs");
}

#[test]
fn b124_wizard_focus() {
    let app_js = b124_web_source("app.js");
    let set_step = b124_function(&app_js, "function wizSetStep(");
    assert!(
        set_step.contains("wizFocusStep(s)"),
        "wizSetStep focuses the new step"
    );
    let focus = b124_function(&app_js, "function wizFocusStep(s) {");
    assert!(focus.contains(".focus()"), "wizFocusStep focuses");
    // The wizard opens with the focus in its step: focus needs the wizard shown first
    let check = b124_function(&app_js, "async function checkSetupWizard() {");
    let shown = check
        .find("show('setup-wizard');")
        .expect("checkSetupWizard shows the wizard");
    assert!(
        check[shown..].contains("wizFocusStep(wizStep)"),
        "checkSetupWizard focuses the step once the wizard is shown"
    );
}

#[test]
fn b124_wizard_finish_holds_back_and_scans() {
    let app_js = b124_web_source("app.js");
    // Back waits for a running Finish
    let prev = b124_function(&app_js, "async function wizPrev() {");
    assert!(prev.contains("wizFinishing"), "wizPrev waits for Finish");
    // Library scans start once the setup is complete, so a replaced library is never mid-scan
    let complete = b124_function(&app_js, "async function wizComplete() {");
    let done = complete
        .find("await API.completeStartup()")
        .expect("wizComplete completes the setup");
    let scan = complete
        .find("API.scanLibrary(")
        .expect("wizComplete starts the scans");
    assert!(done < scan, "the scans start after completeStartup");
}

#[test]
fn b124_every_wizard_step_has_one_primary_button() {
    let html = b124_web_source("index.html");
    let mut n = 0;
    while let Some(start) = html.find(&format!("id=\"wiz-step-{n}\"")) {
        let rest = &html[start..];
        let end = rest
            .find(&format!("id=\"wiz-step-{}\"", n + 1))
            .or_else(|| rest.find("\n</div>\n"))
            .unwrap();
        let primaries = rest[..end].matches("class=\"jf-btn-primary\"").count();
        assert_eq!(primaries, 1, "wiz-step-{n} has one primary button");
        n += 1;
    }
    assert!(n >= 4, "found {n} wizard steps");
}

#[test]
fn b124_wizard_next_runs_once() {
    b124_node_test("b124_wizard_next.mjs");
}

