    let sports = j6_add_item(&state, lib.library, None, "Comet Match", "Movie").await;
    let news = j6_add_item(&state, lib.library, None, "Comet Report", "Movie").await;
    j6_set_text(&state, kids, "tags", "Family|Kids").await;
